"""Hand-coded synthesis toolkit for the keygen tune.

Everything is built so that looped samples are *exactly* periodic inside their
loop: every partial completes an integer number of cycles inside the buffer, so
the tracker loop point never clicks or "phase jumps".
"""
import numpy as np, wave

SR = 44100
NOTE0 = 48            # C2 used as reference pitch for bass/pads (midi 48)


def midi_hz(m):
    return 440.0 * 2.0 ** ((m - 69) / 12.0)


def write_wav(path, x, sr=SR):
    x = np.asarray(x, dtype=np.float64)
    if x.ndim > 1:
        x = x[:, 0] * 0.5 + x[:, 1] * 0.5
    peak = np.abs(x).max()
    if peak > 0.999:
        x = x / peak * 0.999
    data = (x * 32767.0).astype('<i2')
    with wave.open(path, 'wb') as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(sr)
        w.writeframes(data.tobytes())


def read_wav(path):
    with wave.open(path, 'rb') as w:
        n = w.getnframes()
        x = np.frombuffer(w.readframes(n), dtype='<i2').astype(np.float64) / 32768.0
    return x


def norm(x, target=0.9):
    p = np.abs(x).max()
    return x * (target / p) if p > 1e-9 else x


def softclip(x, drive=1.0):
    return np.tanh(x * drive) / np.tanh(drive)


def rng(n, seed=0):
    return np.random.default_rng(seed).standard_normal(n)


# ---------------------------------------------------------------- periodic utils
def n_cycles(freq_ratio, k):
    """integer number of fundamental cycles of a voice inside the loop"""
    return max(1, int(round(k * freq_ratio)))


def additive(L, cycles, amps, phases=None, tilt=0.0):
    """Sum of sine partials whose frequency = cycles*n*(fs/L) -> perfectly loopable."""
    t = np.arange(L) / L
    y = np.zeros(L)
    if phases is None:
        phases = np.zeros(len(amps))
    for n, a, ph in zip(range(1, len(amps) + 1), amps, phases):
        f = cycles * n
        if f >= L / 2.0:          # above Nyquist for this buffer
            break
        y += a * np.sin(2 * np.pi * f * t + ph)
    if tilt:
        y *= np.exp(-tilt * np.arange(L) / L)
    return y


def saw_amps(nharm, rolloff=1.0, tilt=0.0):
    n = np.arange(1, nharm + 1)
    return (1.0 / n ** rolloff) * (1.0 / (1.0 + tilt * (n - 1)))


def pulse_amps(nharm, duty, tilt=0.0):
    n = np.arange(1, nharm + 1)
    a = np.abs(np.sin(np.pi * n * duty) / (np.pi * n))
    return a * (1.0 / (1.0 + tilt * (n - 1)))


def detune_cycle(cents):
    return 2.0 ** (cents / 1200.0)


def lp(x, fc, sr=SR):
    """one-pole lowpass, fc scalar or array (per sample)"""
    x = np.asarray(x, float)
    if np.isscalar(fc):
        a = np.exp(-2 * np.pi * fc / sr)
        y = np.empty_like(x)
        acc = 0.0
        # vectorised-ish: use lfilter style recursion via cumulative trick
        b = 1.0 - a
        y = _one_pole(x, a, b)
        return y
    a = np.exp(-2 * np.pi * np.asarray(fc, float) / sr)
    y = np.empty_like(x)
    acc = 0.0
    for i in range(len(x)):
        acc = a[i] * acc + (1 - a[i]) * x[i]
        y[i] = acc
    return y


def _one_pole(x, a, b):
    # y[n] = a*y[n-1] + (1-a)*x[n]
    from numpy import cumprod
    y = np.empty_like(x)
    # exact recursion via scipy-free approach (fast enough with python for short bufs)
    acc = 0.0
    for i in range(len(x)):
        acc = a * acc + b * x[i]
        y[i] = acc
    return y


def svf(x, fc, res=0.8, sr=SR):
    """state variable lowpass, fc may be an array (per-sample cutoff, Hz)"""
    x = np.asarray(x, float)
    n = len(x)
    fc = np.full(n, fc, float) if np.isscalar(fc) else np.asarray(fc, float)
    fc = np.clip(fc, 30.0, sr * 0.45)
    f = 2 * np.sin(np.pi * fc / sr)
    q = 1.0 / max(res, 0.05)
    y = np.empty(n)
    low = 0.0
    band = 0.0
    for i in range(n):
        low += f[i] * band
        high = x[i] - low - (1.0 / q) * band
        band += f[i] * high
        y[i] = low
    return y


def hp(x, fc, sr=SR):
    return x - lp(x, fc, sr)


def env_exp(L, tau_samples):
    t = np.arange(L)
    return np.exp(-t / tau_samples)


def adsr(n_samples, a, d, s, r, sus_len, sr=SR):
    """piecewise envelope, returns array of n_samples"""
    na, nd, nr = int(a * sr), int(d * sr), int(r * sr)
    ns = int(sus_len * sr)
    e = np.zeros(na + nd + ns + nr)
    if na:
        e[:na] = np.linspace(0, 1, na, endpoint=False)
    if nd:
        e[na:na + nd] = np.linspace(1, s, nd, endpoint=False)
    e[na + nd:na + nd + ns] = s
    if nr:
        e[na + nd + ns:] = np.linspace(s, 0, nr)
    if len(e) < n_samples:
        e = np.concatenate([e, np.zeros(n_samples - len(e))])
    return e[:n_samples]


def midi_name(m):
    names = 'C C#D D D#E E F F#G G G#A A A#B'.split()
    return names[int(m) % 12] + str(int(m) // 12 - 1)
