completes an integer number of cycles inside the buffer -> seamless loops."""
import numpy as np, wave

SR = 44100
NOTE0 = 60                 # sample assigned to note 60  => rendered f = f0/2


def midi_hz(m):
    return 440.0 * 2.0 ** ((m - 69) / 12.0)


