    return d


def norm(x, target=0.9):
    p = np.abs(x).max()
    return x * (target / p) if p > 1e-12 else x


def softclip(x, d=1.0):
    return np.tanh(x * d) / np.tanh(d)


def rng(n, seed=0):
    return np.random.default_rng(int(seed)).standard_normal(n)


def cycles_for(freq, dur):
    return max(1, int(round(freq * dur)))


def wave_add(L, cycles, amps, phases=None):
    i = np.arange(L)
    ph = np.zeros(len(amps)) if phases is None else np.asarray(phases, float)
    y = np.zeros(L)
    nyq = 0.45 * L
    for n in range(1, min(len(amps), len(ph)) + 1):
        k = cycles * n
        if k > nyq:
            break
        y += amps[n - 1] * np.sin(2 * np.pi * k * i / L + ph[n - 1])
    return y


def saw_amps(nh, roll=1.0, tilt=0.0):
    n = np.arange(1, nh + 1, dtype=float)
    return (1.0 / n ** roll) / (1.0 + tilt * (n - 1))


def detune(cents):
    return 2.0 ** (cents / 1200.0)


def lp1(x, fc, sr=SR):
    x = np.asarray(x, float)
    if np.isscalar(fc):
        a = np.exp(-2 * np.pi * fc / sr); b = 1 - a
        y = np.empty_like(x); acc = 0.0
        for i in range(len(x)):
            acc = a * acc + b * x[i]; y[i] = acc
        return y
    fc = np.asarray(fc, float)
    a = np.exp(-2 * np.pi * fc / sr); b = 1 - a
    y = np.empty_like(x); acc = 0.0
    for i in range(len(x)):
        acc = a[i] * acc + b[i] * x[i]; y[i] = acc
    return y


def hp1(x, fc, sr=SR):
    return x - lp1(x, fc, sr)


def hp1f(x, fc, sr=SR):
    """fast Butterworth highpass (zero phase, for one-shots)"""
    from numpy.linalg import inv
    from scipy_stub import lfilter
    return lfilter(fc, x, sr, 'high', 2)


def svf(x, fc, q=0.7, sr=SR):
    x = np.asarray(x, float)
    n = len(x)
    fc = np.full(n, float(fc)) if np.isscalar(fc) else np.asarray(fc, float)
    fc = np.clip(fc, 40.0, sr * 0.44)
    f = 2 * np.sin(np.pi * fc / sr)
    a = 1.0 / max(q * 2 + 0.5, 0.1)
    low = 0.0; band = 0.0
    y = np.empty(n)
    for i in range(n):
        low += f[i] * band
        hi = x[i] - low - a * band
        band += f[i] * hi
        y[i] = low
    return y


def bp_noise(x, f, q=1.0, sr=SR):
    """fast zero-phase band-pass via FFT (one-shot material)"""
    X = np.fft.rfft(x)
    fr = np.fft.rfftfreq(len(x), 1 / sr)
    f = np.atleast_1d(np.asarray(f, float))
    if f.size == 1:
        g = 1.0 / (1.0 + (np.abs(fr / f[0] - 1.0) * q) ** 2)
    else:
        g = np.zeros(len(fr))
    if f.size > 1:
        # time varying: approximate with average (only used for static shells)
        g = 1.0 / (1.0 + (np.abs(fr / np.mean(f) - 1.0) * q) ** 2)
    return np.fft.irfft(X * g, len(x))


def bandpass(x, lo, hi, order=3, sr=SR):
    """zero-phase FFT brick-ish bandpass with given soft edges"""
    X = np.fft.rfft(x)
    fr = np.fft.rfftfreq(len(x), 1 / sr)
    g = np.ones(len(fr))
    if lo is not None:
        g *= 1 / np.sqrt(1 + (lo / np.maximum(fr, 1e-6)) ** (2 * order))
    if hi is not None:
        g *= 1 / np.sqrt(1 + (fr / hi) ** (2 * order))
    return np.fft.irfft(X * g, len(x))


def xfade_tail(x, ms=4):
    n = int(ms * SR / 1000)
    x = np.array(x, float)
    x[-n:] *= np.linspace(1, 0, n)
    return x


def midi_name(m):
    nm = 'C C#D D#E F F#G G#A A#B'.split()
    m = int(m)
    return nm[m % 12] + str(m // 12 - 1)
