def load(p):
    w=wave.open(p); n=w.getnframes()
    d=np.frombuffer(w.readframes(n),dtype='<i2').reshape(-1,2).astype(float)/32768
    return d, w.getframerate()

def stats(p, bartime=2.0, label=''):
    d,sr=load(p)
    print(f'== {label or p}: dur={len(d)/sr:.2f}s peak={np.abs(d).max():.3f} rms={np.sqrt((d**2).mean()):.4f} '
          f'clip={(np.abs(d)>=0.999).sum()}')
    nb=int(len(d)/sr/bartime)
    lines=[]
    for i in range(nb):
        seg=d[int(i*bartime*sr):int((i+1)*bartime*sr)]
        rms=np.sqrt((seg**2).mean()); pk=np.abs(seg).max()
        # band energy
        F=np.abs(np.fft.rfft(seg*np.hanning(len(seg))))**2
        f=np.fft.rfftfreq(len(seg),1/sr)
        def band(a,b): 
            m=(f>=a)&(f<b); return float(F[m].sum()/F.sum())
        lines.append(f'{i:2d} rms={rms:.3f} pk={pk:.2f} lo={band(20,120):.2f} mid={band(300,2500):.2f} hi={band(6000,20000):.2f}')
    for j in range(0,len(lines),1):
        print('  ',lines[j])
    return d

if __name__=='__main__':
